    use std::thread;
    use std::path::Path;

    pub fn process_files(input_dir: &Path, log: Arc<Mutex<log::Logger>>) {
        let mut errors = vec![];

        // Use rayon's parallel iteration to batch-process files concurrently.
        input_dir.read_dir().unwrap().par_iter().for_each(|entry| {
            let log = log.clone();
            let path = entry.unwrap().path();

            match process_file(&path, &log) {
                Ok(_) => (),
                Err(error) => {
                    errors.push(error);
                    log.lock().unwrap().error(&format!("Error processing file: {}", path.display()));
                }
            }
        });

        // Log and handle errors encountered during batch processing.
        if !errors.is_empty() {
            let error_message = errors.iter().map(|e| e.to_string()).collect::<Vec<String>>().join("\n");
            log.lock().unwrap().error(&format!("Encountered errors while processing files:\n{}", error_message));
        }
    }

