        let llvm_module = generator::LLVMGenerator.generate(&ast)?;

        // Use an external logging system to log LLVM IR code generation progress and errors.
        log.lock().unwrap().debug(&format!("Generated LLVM IR for file: {}", path.display()));

        Ok(())
    }
