    std::mutex mtx;
    size_t validationCalls = 0;
    static size_t s_validationCalls;
    static CURL *g_curl;
    static std::function<void(const char *, const char *, size_t, const char *)> logError;

public:
    void appendOrLogDependencyError(const std::string &dependency, const std::function<bool(const std::string &)> &validateDependency) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = dependencies.begin();
        auto end = dependencies.end();

        if (validationCalls > 10000) {
            validationCalls = 0;
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
        ++validationCalls;

        bool foundDependency = false;
        for (; it != end && !foundDependency; ++it) {
            if (*it == dependency) {
                foundDependency = true;
                break;
            }
        }

        if (validateDependency(dependency)) {
            if (!foundDependency) {
                dependencies.push_back(dependency);
            }
        } else {
            char errorLog[1024];
            snprintf(errorLog, sizeof(errorLog), "Failed to validate dependency '%s' due to internal validation error.", dependency.c_str());
            logError(errorLog, "", 0, "");
        }
