angular.module('app')
  .factory('DynamicDialogService', ['$resource', '$q', '_', function($resource, $q, _) {
    var apiUrl = 'http://configuration-api.com'; // Replace with the actual API URL

    var Books = $resource(apiUrl + '/books/:id', {}, {
      query: { method: 'GET', isArray: true }
    });

    function DynamicDialogService($scope, resourceId) {
      this.$scope = $scope;
      this.resourceId = resourceId;
      this.fieldsToRefresh = [];
      this.cachedData = {};
      this.regexPattern = /Old\sTestament/i; // Regex pattern for books of the Old Testament

      var self = this;

      // Load configuration from the API and set the fields to refresh
      $resource(apiUrl + '/config/:id').get({ id: resourceId }, function(data) {
        self.fieldsToRefresh = data.fieldsToRefresh;
      });
    }

    DynamicDialogService.prototype.refreshFields = function() {
      var deferred = $q.defer();
      var dataPromises = [];

      // Iterate through the fields to refresh and make API calls
      angular.forEach(this.fieldsToRefresh, function(field) {
        var cacheKey = this.resourceId + '.' + field;
        var cachedData = this.cachedData[cacheKey];

        if (cachedData && !angular.isFunction(cachedData.then)) {
          // Use cached data when available
          dataPromises.push($q.when(cachedData));
        } else {
          // Make an API call and store the result in cache for future requests
          var apiUrl = this.apiUrl + '/' + this.resourceId + '/' + field;
          dataPromises.push(Books.get({ id: this.resourceId, field: field }, function(data) {
            this.cachedData[cacheKey] = data;
          }));
        }
      }, this);

      // Wait for all API calls to complete and merge the results
      $q.all(dataPromises).then(function(results) {
        self.$scope.$apply(function() {
          // Update the dialog fields with the refreshed data
          angular.forEach(self.fieldsToRefresh, function(field, index) {
            var updatedField = results[index];

            if (angular.isObject(updatedField)) {
              self.$scope[field] = updatedField;
            } else {
              // Handle the case when a single value is returned instead of an object
              self.$scope[field] = JSON.parse(updatedField);
            }
          });
        });
      }, function(error) {
        // Handle errors by logging and providing fallback mechanisms
        console.error('Error refreshing dialog fields:', error);
      }).finally(function() {
        deferred.resolve();
      });

      return deferred.promise;
    };

    DynamicDialogService.prototype.countBooks = function(text) {
      var matches = _.words(text).filter(_.matches(this.regexPattern)).length;
      return matches;
    };

    return DynamicDialogService;
  }]);
