['```javascript
const EventEmitter = require('events');
const axios = require('axios');
const q = require('q');
const asyncQueue = require('async-queue');
const lodash = require('lodash');
const memfs = require('memfs');
const yaml = require('js-yaml');

class DataStreamer extends EventEmitter {
  constructor(options) {
    super();
    this.sources = {};
    this.queue = asyncQueue((task, callback) => callback(null, task()));
    this.maxRetries = options.maxRetries || 3;
    this.themeCache = new memfs.FS();
    this.applyThemeCallbacks = [];

    // Load themes from a yaml file
    const themeFile = memfs.readFileSync(`themes.yaml`, 'utf8');
    this.themes = yaml.load(themeFile);
  }

  addSource(sourceId, url) {
    if (!this.sources[sourceId]) {
      this.sources[sourceId] = {
        id: sourceId,
        url,
        status: 'idle',
        retryCount: 0
      };
    }
  }

  startSource(sourceId) {
    const source = this.sources[sourceId];
    if (source && source.status === 'idle') {
      this.queue.push(() => this._fetchData(source));
    }
  }

  pauseSources() {
    for (const source in this.sources) {
      this.sources[source].status = 'paused';
    }
  }

  resumeSources() {
    for (const source in this.sources) {
      if (this.sources[source].status === 'idle') {
        this.startSource(source);
      }
    }
  }

  _fetchData(source) {
    const self = this;
    return axios.get(source.url).catch((err) => {
      if (source.retryCount < this.maxRetries) {
        source.retryCount++;
        setTimeout(() => self._fetchData(source), 5000);
      } else {
        source.status = 'error';
        self.emit('error', `${source.id}: Failed to fetch data after ${this.maxRetries} retries`);
      }
    });
  }

  processData(data) {
    // Normalize and integrate the incoming data here
    // ...
  }

  getData() {
    const processedData = {};
    for (const source in this.sources) {
      if (this.sources[source].status !== 'error') {
        processedData[source] = this.processData(this.sources[source].data);
      }
    }
    return processedData;
  }

  applyTheme(themeName) {
    const theme = this.themes[themeName];
    if (theme) {
      this.themeCache.chdirSync('/');
      this.themeCache.mkdirpSync(theme.folder);
      for (const file in theme.files) {
        this.themeCache.writeFileSync(`${theme.folder}/${file}`, theme.files[file]);
      }
      this.applyThemeCallbacks.forEach((callback) => callback(this.themeCache));
    } else {
      console.error(`Unknown theme "${themeName}"`);
    }
  }

  onApplyThemeChange(callback) {
    this.applyThemeCallbacks.push(callback);
  }
}

module.exports = DataStreamer;
```

