```c
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>

void executeCommandBackground(const char *command) {
    pid_t pid = fork();

    if (pid == -1) { // Error during fork
        perror("Error forking process");
        return;
    } else if (pid == 0) { // Child process
        execlp(command, command, NULL);
        perror("Error executing command");
        _exit(1);
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status)) {
            if (WEXITSTATUS(status) != 0)
                logError("Command execution failed with exit code: %d", WEXITSTATUS(status));
        } else if (WIFSIGNALED(status)) {
            logError("Command was terminated by signal: %d", WTERMSIG(status));
        } else {
            logError("Unexpected error during command execution");
        }
    }
}
