class JsonHandler:
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.factories = {factory_id: self._get_factory(factory_id) for factory_id in config.get("factories", [])}

    async def _get_schema(self, schema_id: str) -> Model:
        try:
            return await fetch_schema(schema_id)
        except Exception as e:
            logging.error(f"Failed to fetch schema {schema_id}: {e}")
            raise

    def _get_factory(self, factory_id: str) -> Any:
        try:
            module_path, class_name = factory_id.rsplit(".", 2)
            __import__(module_path)
            return getattr(__import__(module_path), class_name)
        except Exception as e:
            logging.error(f"Failed to load factory {factory_id}: {e}")
            raise

    def from_json(self, json_string: str, schema_id: Union[str, None] = None) -> Any:
        if schema_id is not None:
            try:
                model = self._get_schema(schema_id)
                return model.load(json.loads(json_string), validate=True)
            except (DataValidationException, Exception) as e:
                logging.error(f"Invalid JSON data for schema {schema_id}: {e}")
                raise
        else:
            try:
                json_data = json.loads(json_string)
                for factory in self.factories.values():
                    schema_id, _ = factory._meta["schema_id"]
                    try:
                        return factory.load(json_data, validate=True)
                    except (DataValidationException, Exception):
                        pass
                raise ValueError("Unknown JSON data format")

    def to_json(self, obj: Any) -> str:
        schema_id = self._get_schema_id(obj)
        return json.dumps(self.from_json(json.dumps(obj), schema_id)) if schema_id else json.dumps(obj)

    def _get_schema_id(self, obj: Any) -> Union[str, None]:
        for factory in self.factories.values():
            if isinstance(obj, factory):
                return factory._meta["schema_id"][0]
        return None

