std::tuple<std::uint64_t, double, ErrorSummary> processAndHandleTransactions(const std::vector<Transaction>& transactions, ThirdPartyPaymentAPI& api) {
    constexpr size_t batchSize = 10; // Adjust this value based on your API's concurrency limits

    ErrorSummary errorSummaryCopy; // Create a copy of the error summary for each call to processTransaction
    std::queue<Transaction> transactionQueue(transactions.begin(), transactions.end());
    std::vector<std::thread> threads;
    std::mutex mtx;

    while (!transactionQueue.empty()) {
        std::vector<Transaction> batch;
        for (size_t i = 0; i < batchSize && !transactionQueue.empty(); ++i)
            batch.push_back(transactionQueue.front());
            transactionQueue.pop();

        threads.push_back(std::thread(processTransaction, std::ref(batch[0]), std::ref(api)));
        for (size_t i = 1; i < batch.size(); ++i) {
            if (threads.empty()) { // Start a new thread if the current one has completed
                threads.push_back(std::thread(processTransaction, std::ref(batch[i]), std::ref(api)));
            }
        }

        for (auto& t : threads)
            t.join();

        errorSummaryMutex.lock();
        errorSummaryCopy = errorSummary;
        errorSummaryMutex.unlock();

        MonitoringService::updateMetrics(errorSummaryCopy.deserializationErrors, errorSummaryCopy.apiCallErrors); // Replace with your actual monitoring service function
    }

    std::uint64_t successCount = 0;
    double maxWeightedSum = 0.0;

    errorSummaryMutex.lock();
    auto currentErrorSummary = errorSummary;
    errorSummaryMutex.unlock();

    for (const Transaction& transaction : transactions) {
        if (!currentErrorSummary.deserializationErrors && !currentErrorSummary.apiCallErrors) {
            ++successCount;
            maxWeightedSum = std::max(maxWeightedSum, transaction.weightedSum);
        }
    }

    return std::make_tuple(successCount, maxWeightedSum, currentErrorSummary);
}
