// Design the attack selection process to be fair and unbiased
int Character::selectAttack() {
    // Prevent repeated calls during cooldown period
    std::lock_guard<std::mutex> lock(notificationMutex);
    if (cooldownTimer > 0) return -1;

    int nextAttackId = attacks.begin()->first;
    attackIds.push_back(nextAttackId); // Log the selected attack ID for debugging and analytics

