using System;
using System.Collections.Generic;
using System.Configuration;
using System.Linq;
using System.Threading;
using UnityEngine;

public abstract class RandomValueGenerator
{
    protected readonly object _syncLock = new object();
    protected IRandomAlgorithm _randomAlgorithm;
    protected double _minValue;
    protected double _maxValue;
    protected long _seed;
    private bool _isInitialized;

    public event Action<long, double, double> ValueGenerated;
    public event Action ConfigurationChanged;

    protected void OnConfigurationChanged() => ConfigurationChanged?.Invoke();
    protected void OnValueGenerated(long seed, double min, double max) => ValueGenerated?.Invoke(seed, min, max);

    protected RandomValueGenerator(IRandomAlgorithm randomAlgorithm)
    {
        _randomAlgorithm = randomAlgorithm;
        InitializeConfiguration();
    }

    public void SetConfiguration(string sectionName)
    {
        var configurationElement = (ConfigurationElement)ConfigurationManager.GetSection(sectionName);
        if (configurationElement == null || !configurationElement.Elements[0].Key.Equals("minValue") || !configurationElement.Elements[1].Key.Equals("maxValue"))
            throw new ArgumentException($"Invalid configuration section '{sectionName}'. Expected 'minValue' and 'maxValue' elements.");

        _minValue = double.Parse(configurationElement.Elements[0].Value);
        _maxValue = double.Parse(configurationElement.Elements[1].Value);
        _seed = DateTime.UtcNow.Ticks;
    }

    protected abstract IRandomAlgorithm GetRandomAlgorithm();

    public T Random<T>(Func<double, T> convertToType)
    {
        lock (_syncLock)
        {
            if (!_isInitialized) Initialize();
        }

        var randomValue = _randomAlgorithm.NextDouble() * (_maxValue - _minValue) + _minValue;
        OnValueGenerated(_seed, _minValue, _maxValue);

        return convertToType(randomValue);
    }

    public double NextDouble() => _randomAlgorithm.NextDouble() * (_maxValue - _minValue) + _minValue;

    private void InitializeConfiguration()
    {
        SetConfiguration("RandomValueGenerator");
    }

    private void Initialize()
    {
        if (_isInitialized) return;

        var randomAlgorithm = GetRandomAlgorithm();
        _randomAlgorithm.SetSeed(_seed);
        _isInitialized = true;
    }

    public override string ToString() => $"Range: {_minValue} - {_maxValue}, Seed: {_seed}";
}

public interface IRandomAlgorithm
{
    double NextDouble();
    void SetSeed(long seed);
}

public class SystemRandomAlgorithm : IRandomAlgorithm
{
    private readonly Random _random = new Random();

    public double NextDouble() => _random.NextDouble();

    public void SetSeed(long seed) => _random.SetSeed(seed);
}

public class UnityEngineRandomAlgorithm : IRandomAlgorithm
{
    public double NextDouble() => UnityEngine.Random.value;

    public void SetSeed(long seed) { } // Unity's random API does not support changing the seed
}
```

