#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef enum {
    JSON,
    CSV,
    INI,
    // Extend for additional file formats
    NUM_FORMATS
} ResourceFormat;

typedef struct ResourceBundle {
    const char *filename;
    ResourceFormat format;
    void *data; // Parsed data structure for the format
    pthread_mutex_t lock;
    struct ResourceBundle *next;
} ResourceBundle;

typedef struct ResourceKeyValue {
    const char *key;
    const char *value;
} ResourceKeyValue;

// API functions
ResourceBundle *ResourceLoad(const char *filename);
bool ResourceUnload(ResourceBundle *bundle);
ResourceKeyValue *ResourceGet(ResourceBundle *bundle, const char *key);

// Internal helper functions (not part of the public API)
static int ParseFile(FILE *, void **parsedData, ResourceFormat format);
static bool ValidateFilename(const char *filename);
static void FreeParsedData(void *data);
static pthread_mutexattr_t mutexAttr;
static pthread_mutex_t bundlesLock;
static ResourceBundle *head = NULL;

// Initialize mutex attributes and locks
pthread_mutexattr_init(&mutexAttr);
pthread_mutexattr_settype(&mutexAttr, PTHREAD_MUTEX_RECURSIVE);
pthread_mutex_init(&bundlesLock, &mutexAttr);

ResourceBundle *ResourceLoad(const char *filename) {
    // Validate filename and open file
    if (!ValidateFilename(filename)) return NULL;
    FILE *file = fopen(filename, "r");
    if (NULL == file) return NULL;

    // Parse the data using the appropriate parser for the file extension
    ResourceFormat format;
    void *data;
    if (ParseFile(file, &data, &format)) {
        free(file);
        return NULL;
    }

    // Allocate a new resource bundle and initialize it with the data
    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    bundle->filename = filename;
    bundle->format = format;
    bundle->data = data;
    pthread_mutex_init(&bundle->lock, &mutexAttr);
    bundle->next = head;
    head = bundle;

    return bundle;
}

bool ResourceUnload(ResourceBundle *bundle) {
    if (NULL == bundle || NULL == head) return false;

    pthread_mutex_lock(&bundlesLock);
    ResourceBundle **current = &head;
    while (*current && *current != bundle) current = &(*current)->next;

    if (!*current) {
        pthread_mutex_unlock(&bundlesLock);
        free(bundle->filename);
        FreeParsedData(bundle->data);
        free(bundle);
        return false;
    }

    *current = bundle->next;
    pthread_mutex_unlock(&bundlesLock);

    free(bundle->filename);
    FreeParsedData(bundle->data);
    free(bundle);

    return true;
}

ResourceKeyValue *ResourceGet(ResourceBundle *bundle, const char *key) {
    if (NULL == bundle || NULL == key) return NULL;

    pthread_mutex_lock(&bundle->lock);
    // Implement the lookup logic based on your chosen data structure and file format
    ResourceKeyValue *result = findKey(bundle->data, key);
    pthread_mutex_unlock(&bundle->lock);

    return result;
}
