namespace bp = boost;
using namespace std::literals;

class BackgroundProcessManager {
public:
    using ProcessId = int64_t;

    ProcessId start(const std::string& command) {
        ++m_nextId;
        auto process = std::make_unique<BackgroundProcess>(m_nextId, command);
        m_processes.emplace(m_nextId, std::move(process));
        process->thread.detach();
        return m_nextId;
    }

    void waitForExit(ProcessId id) {
        std::unique_lock<std::mutex> lock(m_exitStatusMutex);
        if (m_exitStatuses.find(id) != m_exitStatuses.end())
            m_processCompleteCV.wait(lock, [this, id]() { return m_exitStatuses.count(id) == 0; });
    }

    boost::optional<int> getExitStatus(ProcessId id) {
        std::unique_lock<std::mutex> lock(m_exitStatusMutex);
        if (m_exitStatuses.find(id) != m_exitStatuses.end())
            return m_exitStatuses[id];
        return boost::none;
    }

private:
