2. ExternalApiService

```java
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

@Service
public class ExternalApiService {
    private final CloseableHttpClient httpClient = HttpClients.createDefault();

    public byte[] getMetadata(String className, Long id) {
        try {
            String url = "https://example-api.com/metadata?className=" + className + "&id=" + id;
            HttpGet request = new HttpGet(url);
            CloseableHttpResponse response = httpClient.execute(request);

            if (response.getStatusLine().getStatusCode() == 200) {
                return EntityUtils.toByteArray(response.getEntity());
            } else {
                throw new RuntimeException("Error fetching metadata");
            }
        } catch (IOException e) {
            throw new RuntimeException("IO error fetching metadata", e);
        }
    }
}
```

3. DeserializerService

```java
import com.fasterxml.jackson.databind.ObjectMapper;
