const fs = require('fs');
const axios = require('axios');
const fileUploader = require('file-uploader-library'); // Use a suitable file uploader library
const metadataService = require('metadata-service-library'); // Use a suitable metadata service library
const exponentialBackoff = require('exponential-backoff');
const { cancelToken, CancellationTokenSource } = require('axios');

// Configuration options (optional)
const config = {
  retries: 5,
  backoffFactor: 2, // Defaults to 2. Increase for longer delays between retries
  logLevel: 'info',
  metadataServiceFallbackEnabled: false
};

// Utility function to validate input arguments
function validateInput(url, fileMetadata) {
  if (!url || !fileMetadata || !(typeof url === 'string' && typeof fileMetadata === 'object')) {
    throw new Error('Invalid input provided');
  }

  const validTypes = ['image/jpeg', 'image/png', 'application/pdf'];
  if (!validTypes.includes(fileMetadata.type)) {
    throw new Error('Unsupported file type');
  }
}

// Check for file existence in metadata service (if enabled) before uploading
async function checkFileExistence(filename, mdsClient) {
  // Use the metadata service to check if the file already exists
  try {
    const fileData = await mdsClient.getFileInfo({ name: filename });
    return !!fileData;
  } catch (err) {
    console.error(`Error checking file existence: ${err.message}`);
    return false;
  }
}

// Upload file with retries and error handling
async function uploadFileWithRetry(url, fileMetadata, config = {}) {
  validateInput(url, fileMetadata);

  const { retries, backoffFactor, logLevel, metadataServiceFallbackEnabled } = { ...config };
  let attempt = 1;
  let cancelTokenSource;

  // Initialize cancellation token and axios instance
  if (config.cancellationToken) {
    cancelTokenSource = new CancellationTokenSource();
  } else {
    cancelTokenSource = new CancellationTokenSource({ signal: cancelToken });
  }

  const axiosInstance = axios.create({
    baseURL: url,
    cancelToken: cancelTokenSource.token,
    timeout: 60 * 1000 // Set a default timeout of 1 minute
  });

  // Check for file existence and associate metadata (if enabled) before initiating upload
  const shouldUpload = !metadataServiceFallbackEnabled || !(await checkFileExistence(fileMetadata.name, metadataService));

  if (!shouldUpload) {
    console.log(`File already exists; skipping upload...`);
    return;
  }

  let promises = [];

  // Handle file upload with retries and exponential backoff
  const retryStrategy = (error, previousAttempt) => {
    if (previousAttempt >= retries) {
      throw error;
    }

    attempt++;
    console.log(`Upload attempt ${attempt} failed. Retrying in ${Math.pow(2, previousAttempt * backoffFactor)} seconds...`);

    return new Promise((resolve) => {
      setTimeout(() => {
        resolve();
      }, Math.pow(2, (attempt - 1) * backoffFactor) * 1000);
    });
  };

  promises.push(exponentialBackoff(retryStrategy, async () => {
    try {
      const fileStream = fs.createReadStream(fileMetadata.path);

      // Associate metadata with the uploaded file (if enabled)
      if (metadataServiceFallbackEnabled) {
        await metadataService.associateFileWithMetadata({ name: fileMetadata.name, metadata: fileMetadata });
      }

      // Use the file uploader library to handle the actual file upload
      const result = await fileUploader.upload({
        file: fileStream,
        filename: fileMetadata.name,
        contentType: fileMetadata.type
      }, {
        cancelToken: cancelTokenSource.token,
        timeout: 60 * 1000 // Set a default timeout of 1 minute
      });

      console.log(`File uploaded successfully!`);
      return result.url;
    } catch (err) {
      console.error(`Upload attempt ${attempt} failed with error: ${err.message}`);
    }
  }));

  try {
    const fileUrl = await Promise.race(promises);
    return fileUrl;
  } catch (error) {
    console.error(`All upload retries have been exhausted. Error: ${error.message}`);
    throw error;
  }
}
```

Note that this is a simplified example and does not include all the required dependencies, configuration options, and service implementations for external file uploaders and metadata services. You will need to replace the `file-uploader-library`, `metadata-service-library`, `exponential-backoff`, and `axios` imports with actual libraries or modules that suit your project requirements.

Additionally, you may want to consider using a proper logging library like Winston for handling log levels and error messages. And, if you are dealing with large files or high concurrency, ensure the file uploader library supports efficient streaming and multi-part requests."]

