**PHP User Account Management Function:**

```php
function manageUserAccount($request) {
    $db = new PDO('mysql:host=localhost;dbname=myDB', 'username', 'password');
    $errors = [];

    $id = isset($request['id']) ? intval($request['id']) : null;
    $name = trim($request['name']);
    $email = filter_var(trim($request['email']), FILTER_VALIDATE_EMAIL);
    $password = password_hash(trim($request['password']), PASSWORD_BCRYPT);
    $sub_action = trim($request['sub_action']);

    switch ($sub_action) {
        case 'create':
            if (empty($name) || empty($email) || empty($password)) {
                $errors[] = "Name, Email and Password are required.";
            } elseif ($db->query("SELECT COUNT(*) FROM users WHERE email='$email'")->fetchColumn() > 0) {
                $errors[] = "The provided email is already registered.";
            } else {
                $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
                $stmt->execute([$name, $email, $password]);
            }
            break;
        case 'update':
            if (empty($name) || empty($email)) {
                $errors[] = "Name and Email are required.";
            } elseif ($db->query("SELECT COUNT(*) FROM users WHERE email='$email' AND id!=$id")->fetchColumn() > 0) {
                $errors[] = "The provided email is already registered.";
            } else {
                $stmt = $db->prepare("UPDATE users SET name=?, email=? WHERE id=?");
                $stmt->execute([$name, $email, $id]);
            }
            break;
        case 'delete':
            if ($id === null) {
                $errors[] = "ID is required for deleting.";
            } else {
                $stmt = $db->prepare("DELETE FROM users WHERE id=?");
                $stmt->execute([$id]);
            }
            break;
        default:
            $errors[] = "Invalid sub_action provided.";
    }

    http_response_code(200);
    echo json_encode(['success' => empty($errors), 'errors' => $errors]);
}
```']

