class Application {
public:
    explicit Application(const std::string& configFilePath);
    ~Application();

    void run();
private:
    void startServices();
    void stopServices();
    void scheduleTask(std::function<void()> task);

    std::mutex mtx_;
    std::condition_variable cv_;
    std::vector<std::thread> threads_;
    ServiceManager serviceManager_;
    MessagingSystem messagingSystem_;
    DatabaseWrapper databaseWrapper_;
    tcp::resolver resolver_;
    int retryCount_;
    double backoffFactor_;
    long rateLimitWindow_;
    int rateLimit_;
    bool isRunning_;
};

Application::Application(const std::string& configFilePath) {
    bp::ptree pt;
    std::ifstream ifs(configFilePath);
    boost::property_tree::read_json(ifs, pt);

    retryCount_ = pt.get<int>("Retry.Count");
    backoffFactor_ = pt.get<double>("Retry.BackoffFactor");
    rateLimitWindow_ = pt.get<long>("RateLimit.Window");
    rateLimit_ = pt.get<int>("RateLimit.Limit");

    // Initialize Sandesh client, messaging system, and database wrapper based on configuration
}

Application::~Application() {
    stopServices();
}

void Application::startServices() {
    serviceManager_.init(messagingSystem_);
    databaseWrapper_.init();
    resolver_ = tcp::resolver(boost::asio::io_context().get_executor());
    isRunning_ = true;
}

void Application::stopServices() {
    isRunning_ = false;
    serviceManager_.shutdown();
    databaseWrapper_.shutdown();
}

void Application::scheduleTask(std::function<void()> task) {
    std::unique_lock<std::mutex> lock(mtx_);
    tasks_.emplace_back(task);
    cv_.notify_one();
}

void workerThread() {
    Application& app = *(Application*)workerData;
    while (app.isRunning_) {
        std::function<void()> task;
        {
            std::unique_lock<std::mutex> lock(app.mtx_);
            app.cv_.wait(lock, [&app]() { return !app.tasks_.empty(); });
            task = app.tasks_.front();
            app.tasks_.pop_front();
        }
        task();
    }
}

void Application::run() {
    startServices();

    for (size_t i = 0; i < numThreads_; ++i) {
        threads_.emplace_back(std::thread(&workerThread, this));
    }

