    std::unique_ptr<std::istream> is(new std::istreambuf_iterator<char>(*file));
    std::unique_ptr<ObjectInputStream> ois(ObjectInputStream(*is));

    if (!ois->good()) {
        throw LoadStateError("Failed to create ObjectInputStream");
    }

    std::shared_ptr<MoSTState> state;

    std::thread reader([&]() {
        try {
            state = ois->readObject();
        } catch (const std::exception& e) {
            throw LoadStateError("Failed to read state object: " + e.what());
        }
    });

    reader.join();

    if (!state || !std::dynamic_pointer_cast<MoSTState>(state)) {
        throw LoadStateError("Invalid state object");
    }

    std::lock_guard<std::mutex> lk(mtx);

    if (connection && !boost::asio::ip::tcp::is_connected(*connection)) {
        throw LoadStateError("Connection is not connected");
    }

    if (!validatePasswordComplexity(password)) {
        throw LoadStateError("Invalid password");
    }

    if (!callback) {
        throw LoadStateError("Callback function is NULL");
    }

    // Perform any additional checks, optimizations, or resource management here as needed

    ois->close();
    file.close();

    callback(state.get());
    return std::move(state);
}
```']

