```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    char* name;
    int size;
} ResourceItem;

ResourceItem* load_resource_bundle(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    long length = 0;
    char c;
    while ((c = fgetc(file)) != EOF) {
        length++;
    }
    rewind(file);

    ResourceItem* items = (ResourceItem*)malloc((length + 1) * sizeof(ResourceItem));
    if (!items) {
        fprintf(stderr, "Error allocating memory\n");
        return NULL;
    }

    size_t read = 0;
    for (int i = 0; i < length; ++i) {
        items[i].name = fread(&items[i], sizeof(ResourceItem), 1, file);
        if (feof(file)) {
            break;
        }
        read++;
    }

    items[length].name = NULL;

    if (ferror(file)) {
        perror("Error reading file");
        free(items);
        return NULL;
    }

    fclose(file);
    return items;
}

int num_items_in_bundle(ResourceItem* bundle) {
    int count = 0;
    for (int i = 0; bundle[i].name != NULL; ++i) {
        count++;
    }
    return count;
}
