  2. **System Command Execution Service (C++)**

```cpp
#include <iostream>
#include <vector>
#include <future>
#include <sys/wait.h>
#include <unistd.h>
#include <cerrno>

std::future<int> executeCommandBackground(const std::string& command) {
  // Create a new process and store its PID (Process ID)
  pid_t childPid = fork();

  if (childPid == 0) { // Child process
    execlp(command.c_str(), command.c_str(), nullptr);
    perror("Failed to execute command");
    _exit(EXIT_FAILURE);
  } else if (childPid > 0) { // Parent process
    int status;
    waitpid(childPid, &status, 0);
    return std::future<int>(std::async([&]() { return WIFEXITED(status) ? WEXITSTATUS(status) : -1; }));
  } else { // Fork failed (e.g., permission issues or resource exhaustion)
    std::cerr << "Failed to fork: " << strerror(errno) << std::endl;
    return std::future<int>(std::async([]() { return -1; }));
  }
}
```

