        {
            // Implement AWS S3 upload with checksum calculation and storage
            // ...

            // Implement Azure Blob Storage upload with checksum calculation and storage
            // ...

            // Calculate MD5 checksum for the uploaded file
            using (var md5 = MD5.Create())
            {
                var hashBytes = md5.ComputeHash(fileStream);
                var checksum = BitConverter.ToString(hashBytes).Replace("-", "");

                // Store checksum in metadata database
                await MetadataDatabase.StoreChecksumAsync(container, key, checksum);
            }

            return await Task.FromResult<PutObjectResponse>(new PutObjectResponse());
        }

        public async Task<Stream> DownloadFileAsync(string container, string key)
        {
            // Implement AWS S3 download with checksum calculation for verification
            // ...

            // Implement Azure Blob Storage download with checksum calculation for verification
            // ...

            return await Task.FromResult<Stream>(new MemoryStream());
        }
    }

    public class FileIntegrityChecker
    {
        private readonly ConcurrentDictionary<(string, string), Task> _uploadTasks = new ConcurrentDictionary<(string, string), Task>();
        private readonly ConcurrentDictionary<(string, string), Task> _downloadTasks = new ConcurrentDictionary<(string, string), Task>();
        private readonly ICloudStorageService _cloudStorage;
        private readonly MetadataDatabase _metadataDatabase;

        public FileIntegrityChecker(ICloudStorageService cloudStorage, MetadataDatabase metadataDatabase)
        {
            _cloudStorage = cloudStorage;
            _metadataDatabase = metadataDatabase;
        }

        public async Task UploadFileAsync(string container, string key, Stream fileStream)
        {
            if (_uploadTasks.ContainsKey((container, key)))
                await _uploadTasks[(container, key)].ConfigureAwait(false);

            var uploadTask = _cloudStorage.UploadFileAsync(container, key, fileStream).ContinueWith(task =>
            {
                if (task.IsFaulted)
                    Console.WriteLine($"Error uploading '{key}': {task.Exception}");
            });

            _uploadTasks[(container, key)] = uploadTask;
        }

        public async Task<Stream> DownloadFileAsync(string container, string key)
        {
            if (_downloadTasks.ContainsKey((container, key)))
                await _downloadTasks[(container, key)].ConfigureAwait(false);

            var downloadTask = _cloudStorage.DownloadFileAsync(container, key).ContinueWith(task =>
            {
                if (task.IsFaulted)
                    Console.WriteLine($"Error downloading '{key}': {task.Exception}");
            });

            _downloadTasks[(container, key)] = downloadTask;
            return await downloadTask.Result;
        }
    }
}
```

