[" ```javascript
async function uploadFileWithRetry(url, metadata, config) {
  if (!isValidUrl(url) || !isValidMetadata(metadata)) return Promise.reject('Invalid input');

  const fileUploader = new FileUploaderLibrary();
  let retries = config.retries || 5;
  let backoffDelay = 1000;

  function handleError(error, retryCount) {
    if (retryCount > retries) {
      return Promise.reject(`Upload failed after ${retries} attempts: ${error.message}`);
    }

    // Adapt the backoff strategy based on service response codes and availability
    backoffDelay *= 2;
    backoffDelay += Math.random() * 500; // Jitter factor

    return new Promise(resolve => setTimeout(() => resolve(), backoffDelay));
  }

  const primaryService = new PrimaryFileUploadService();
  const backupService = new BackupFileUploadService();
  const metadataService = new ThirdPartyMetadataService();

  // Check for file existence and manage concurrent updates with conflict resolution
  let checkExistencePromise;
  if (primaryService.exists(metadata.name)) {
    checkExistencePromise = primaryService.getLatestVersion(metadata.name);
    // Conflict resolution logic here
  } else {
    checkExistencePromise = Promise.resolve(null);
  }

  let uploadPromises = [
    ...checkExistencePromise.then(existing => {
      if (existing) return backupService.upload(metadata, config);
      return primaryService.upload(metadata, config);
    }),
    metadataService.associateMetadata(metadata),
  ];

  try {
    await Promise.race(uploadPromises.map(p => p.catch(handleError)));
    return primaryService.getUploadedFileUrl();
  } catch (error) {
    const errorSummary = getErrorSummary(error);
    return Promise.reject(errorSummary);
  }
}

