2. C++ OAuth2 Access Token Validator:

```cpp
#include <nlohmann/json.hpp>
#include <stdexcept>

bool validateOAuth2AccessToken(const std::string& token) {
    try {
        nlohmann::json j = nlohmann::json::parse(token);

        if (!j.is_object()) throw std::invalid_argument("Invalid JSON object");
        if (j.find("token_type") == j.end() || j["token_type"] != "Bearer") throw std::runtime_error("Missing or invalid 'token_type' field");
        if (!j.count("expires_in")) throw std::runtime_error("Missing 'expires_in' field");
        if (j["expires_in"] <= 0) throw std::runtime_error("Negative or zero 'expires_in' value");
    } catch(const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return false;
    }

    return true;
}
```

