        std::vector<int>& vec,
        std::function<void(CompareFunc, int&)> callback) {
    // Initialize performance metrics
    auto start = high_resolution_clock::now();

    // Create a map to store fetched data and its metadata
    std::map<int, CompareFunc> dataMap;

    // Parallelize the fetching and sorting using threads
    std::vector<std::thread> threads;
    std::mutex mtx;
