                    stop.store(true, std::memory_order_release);
                })) {
                // Log an error if fetching fails
            }
        });
    }
    for (auto& t : threads) {
        t.join();
    }

    // Sort the vector and merge it with fetched data, preserving even numbers first
    std::vector<int> sortedVec;
    for (const auto& [id, cf] : dataMap) {
        int number;
        if (cf.compare(number, number)) {
            // Log an error and continue if comparator function fails validation
            continue;
        }
        number = id;
        sortedVec.push_back(number);
