#include "LTE_PHY_RX_TARGETED_INFO.h" // Assuming you have a defined LTE_PHY_RX_TARGETED_INFO structure

typedef struct {
    LTE_PHY_RX_TARGETED_INFO* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    semaphore_t resize_semaphore; // Control concurrent access to the array during resizing
} dynamic_array_t;

static void init_dynamic_array(dynamic_array_t* arr, size_t capacity) {
    arr->data = malloc(capacity * sizeof(LTE_PHY_RX_TARGETED_INFO));
    if (!arr->data) {
        // Handle error and log
        return;
    }

    arr->capacity = capacity;
    arr->count = 0;
    pthread_mutex_init(&arr->lock, NULL);
    sem_init(&arr->resize_semaphore, 0, 1); // Initial value is 1, indicating resizing is not in progress
}

static void push(dynamic_array_t* arr, const LTE_PHY_RX_TARGETED_INFO* item) {
    if (arr->count >= arr->capacity) {
        sem_wait(&arr->resize_semaphore); // Block until resizing is not in progress
        resize(arr, arr->capacity * 2); // Double the capacity when full
        sem_post(&arr->resize_semaphore);
    }

    pthread_mutex_lock(&arr->lock);
    arr->data[arr->count] = *item;
    ++arr->count;
    pthread_mutex_unlock(&arr->lock);
}

static void resize(dynamic_array_t* arr, size_t new_capacity) {
    LTE_PHY_RX_TARGETED_INFO* new_data = realloc(arr->data, new_capacity * sizeof(LTE_PHY_RX_TARGETED_INFO));
    if (!new_data) {
        // Handle error and log
        return;
    }

    arr->data = new_data;
    arr->capacity = new_capacity;
}

