#pragma once
#include <deque>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <thread>
#include <atomic>

class CELLULAR_EVENT_RECORD {
public:
    enum class PRIORITY : int { LOW, MEDIUM, HIGH };
    std::string identifier;
    PRIORITY priority;
    std::uint64_t timestamp;

    CELLULAR_EVENT_RECORD(const std::string& id, PRIORITY p, std::uint64_t ts) : identifier(id), priority(p), timestamp(ts) {}
};

class DynamicQueue {
private:
    std::deque<CELLULAR_EVENT_RECORD> data;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<int> capacity{1024};
    int head = 0, tail = 0;

public:
    void Initialize(int cap) { capacity = cap; }
    bool Empty() const { return head == tail; }
    void PushBack(const CELLULAR_EVENT_RECORD& record);
    const CELLULAR_EVENT_RECORD& Front();
    void PopFront();
};

void DynamicQueue::PushBack(const CELLULAR_EVENT_RECORD& record) {
    std::unique_lock<std::mutex> lock(mtx);
    if ((tail + 1) % capacity == head) {
        cv.wait(lock, [this] { return (tail + 1) % capacity != head; });
    }
    data[tail] = record;
    tail = (tail + 1) % capacity;
}

const CELLULAR_EVENT_RECORD& DynamicQueue::Front() {
    std::unique_lock<std::mutex> lock(mtx);
    return data[head];
}

void DynamicQueue::PopFront() {
    std::unique_lock<std::mutex> lock(mtx);
    CELLULAR_EVENT_RECORD record = Front();
    head++;
    cv.notify_one();
}
```

