            return -1; // Handle error code appropriately
        }

        Json::CharReaderBuilder builder;
        Json::CharReader* reader = builder.newCharReader();
        Json::Value root;

        std::string contents((std::istreambuf_iterator<decltype(ifs)>(ifs)),
                              (std::istreambuf_iterator<decltype(ifs)>()));
        bool parsed = reader->parse(contents, root, nullptr);
        delete reader;

        if (!parsed) {
            return -2; // Handle error code appropriately
        }

        int itemCount = root["items"].size();
        numItems_ = itemCount;

        return itemCount;
    }

    int getNumItems() const {
        return numItems_;
    }

private:
    mutable pthread_mutex_t mutex; // Mutex for thread safety
