['1. Logging Framework (LoggingModule.java)

```java
package com.example.logging;

import org.apache.logging.log4j.core.appender.AbstractAppender;
import org.slf4j.LoggerFactory;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.AppenderBase;
import com.example.logging.config.LoggingConfig;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public abstract class LoggingModule {
    protected final String moduleName;
    protected LoggerFactory loggerFactory;
    protected AbstractAppender<ILoggingEvent> appender;
    protected AppenderBase<ILoggingEvent> logbackAppender;
    protected LoggingConfig config;

    public LoggingModule(String moduleName) {
        this.moduleName = moduleName;
    }

    protected void init() {
        loggerFactory = LoggerFactory.getLogger(getClass());
        config = new LoggingConfig(); // Load configuration from dynamic source
        createAppender();
        registerLoggers();
    }

    protected abstract void createAppender();

    private void registerLoggers() {
        for (Class<?> clazz : getLoggableClasses()) {
            loggerFactory.getLogger(clazz).addAppender(appender);
        }
    }

    protected abstract Class<?>[] getLoggableClasses();

    public void logInfo(String message) {
        appender.doAppend(createEvent("INFO", message));
    }

    public void logDebug(String message) {
        appender.doAppend(createEvent("DEBUG", message));
    }

    public void logError(Throwable throwable, String message) {
        appender.doAppend(createEvent("ERROR", message, throwable));
    }

    private ILoggingEvent createEvent(String level, String message) {
        return new ILoggingEvent(level, this.moduleName, this.moduleName, 0, System.currentTimeMillis(), message);
    }

    private ILoggingEvent createEvent(String level, String message, Throwable throwable) {
        return new ILoggingEvent(level, this.moduleName, this.moduleName, 0, System.currentTimeMillis(), message, throwable);
    }

    public static String sha256(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hash = digest.digest(input.getBytes(StandardCharsets.UTF_8));
        StringBuilder sb = new StringBuilder();
        for (byte b : hash) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
```

