import org.elasticsearch.client.RestHighLevelClient;
import java.io.IOException;
import java.util.Map;

public class ElasticsearchAppender extends AbstractAppender<LogEvent> {
    private final RestHighLevelClient client;
    private String indexName;

    public ElasticsearchAppender(String indexName, RestHighLevelClient client) {
        super(null);
        this.indexName = indexName;
        this.client = client;
    }

    @Override
    protected void append(LogEvent logEvent) {
        try {
            IndexRequest request = new IndexRequest(indexName).source(logEvent.getMessage(), "level", logEvent.getLevel().toString());
            client.index(request, RequestOptions.DEFAULT);
        } catch (IOException e) {
            // Handle exceptions and retry/fallback strategies
        }
    }
}
```

