int chooseBackend(const std::vector<double>& weights) {
    std::uniform_int_distribution<> distribution(0, weights.size() - 1);
    std::mt19937 engine;
    engine.seed(std::chrono::high_resolution_clock::now().time_since_epoch().count());

    int index = distribution(engine) / (double)weights.size();
    double sum = 0.0;
    for (int i = 0; i < weights.size(); ++i) {
        sum += weights[i];
        if (sum >= index) return i;
    }
}
