// Fallback RNG algorithm (XorShift128+)
class FallbackRng {
public:
    uint64_t state[2] = {1, 0};

    uint32_t next() {
        constexpr uint64_t mask = UINT64_C(0xffffffff);
        uint64_t old = state[1];
        state[1] = (old * 1812433253UL) + 1;
        state[0] ^= old >> 30;
        return static_cast<uint32_t>((old << 30) | (state[0] >> 2));
    }
};

// Mersenne Twister RNG implementation
class MersenneTwister {
private:
    std::array<unsigned long, 624> mt; // the array for the state vector
    int mti = NDIMENSIONS;              // index of the array mt[].
    unsigned long *mtiNext = &mt[0];    // alias for mt[0]
    unsigned long mag01[2]={0x0UL, MASK32};
    uint32_t mag01p[4]={0x0UL, MASK32, MASK32, MASK32};
    uint32_t rmd(uint32_t a) { return a & MASK32; }
    void init_by_array(unsigned long array[]) {
        int i;
        for (i = 0; i < NDIMENSIONS; i++) {
            mt[i] = array[i];
        }
        mti = NDIMENSIONS;
        for (i = NDIMENSIONS-1; i >= 1; i--) {
            mt[i] = (69069 * mt[i] + 12345) & MASK32;
            if (mt[i] < 0) mt[i] += MASK32;
        }
        mt[0] = (1812433253UL * mt[0] + 12345) & MASK32; // calculated from array seed modulo MASK32
    }
public:
    void setSeed(uint64_t seed) {
        FallbackRng fallback;
        for (int i = 0; i < NDIMENSIONS; i++) {
            mt[i] = static_cast<unsigned long>((seed * fallback.next()) & MASK32);
        }
        mti = NDIMENSIONS;
    }
    unsigned long gen() {
        if (mti >= NDIMENSIONS) {
            int kk;
            for (kk = 0; kk < NDIMENSIONS-NDIMENSIONS/4; ++kk) {
                mtiNext[kk] = (1812433253UL * (mtiNext[kk] & MASK32)) + (uint32_t)(mt[kk]/45075269);
                if (mtiNext[kk] < 0) mtiNext[kk] += MASK32;
                mt[kk] = mtiNext[kk];
            }
            for (; kk < NDIMENSIONS-1; ++kk) {
                mtiNext[kk] = (400UL * (mtiNext[kk+1] & MASK32)) + (uint32_t)(mt[kk]/45075269);
                if (mtiNext[kk] < 0) mtiNext[kk] += MASK32;
                mt[kk] = mtiNext[kk];
            }
            mtiNext[NDIMENSIONS-1] = (21UL * (mt[NDIMENSIONS-1] & MASK32)) + (uint32_t)(mt[(NDIMENSIONS-1)/4] >> 0);
            if (mtiNext[NDIMENSIONS-1] < 0) mtiNext[NDIMENSIONS-1] += MASK32;
            mti = 0;
        }
        unsigned long y = mt[mti++];
        y = y^(y >> 11); y = y ^ (y << 7) & 0x9d2c5680UL; y = y ^ (y << 15) & 0xefc60000UL; y = y ^ (y >> 18);
        return y;
    }
};

