```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *data;
    size_t size;
} ResourceItem;

int loadResources(const char* filename, ResourceItem** resources, size_t* numResources) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    rewind(file);

    ResourceItem *items = (ResourceItem*)malloc(length / sizeof(ResourceItem));
    if (!items) return -2;

    size_t index = 0;
    ResourceItem item;
    while (fscanf(file, "%s", item.data) != EOF) {
        item.size = strlen(item.data);
        items[index++] = item;
    }

    *resources = items;
    *numResources = index;

    fclose(file);
    return 0;
}
