2. **C Function to Load Configuration**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

struct Config {
    char *key;
    char *value;
};

int load_config(const char *filename, struct Config **config, size_t *count) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    long length = lseek(fd, 0, SEEK_END);
    if (length == (long)-1) {
        perror("lseek");
        close(fd);
        return 1;
    }

    char *buffer = malloc(length + 1);
    if (!buffer) {
        perror("malloc");
        close(fd);
        return 1;
    }

    size_t bytes_read = read(fd, buffer, length);
    if (bytes_read != length) {
        perror("read");
        free(buffer);
        close(fd);
        return 1;
    }

    buffer[length] = '\0';
    char *line = strtok(buffer, "\n");
    size_t config_count = 0;
    struct Config *config_array = NULL;
    while (line) {
        config_array = realloc(config_array, sizeof(struct Config) * ++config_count);
        if (!config_array) {
            free(buffer);
            perror("realloc");
            close(fd);
            return 1;
        }

        char *equal = strchr(line, '=');
        if (!equal) {
            continue; // Skip invalid lines
        }

        *equal++ = '\0';
        config_array[config_count - 1].key = strdup(line);
        config_array[config_count - 1].value = strdup(equal);
    }

    free(buffer);
    close(fd);

    *config = config_array;
    *count = config_count;
    return 0;
}
```']

