    void addDependency(const std::string& dependency) {
        // Insert new dependency after the first occurrence of a specified dependency if it exists; otherwise, append it to the end of the list.
        auto it = dependencies.before_begin();
        for (auto depIt = dependencies.begin(); depIt != dependencies.end(); ++depIt) {
            if (*depIt == dependency) {
                it = depIt;
                break;
            }
        }
        dependencies.insert(it, dependency);
    }

    void validateDependencies() {
        // Validate each dependency, handling retries and prioritizing critical dependencies.
        std::vector<std::pair<std::string, int>> priorityDepends;
        for (auto dep : dependencies) {
            priorityDepends.emplace_back(dep, getPriority(dep));
        }
        std::sort(priorityDepends.begin(), priorityDepends.end(), [](const auto& lhs, const auto& rhs) { return lhs.second > rhs.second; });

