                curl_easy_getinfo(curl, CURLINFO_RESPONSE_DATA, errorBuffer, res);

                char errorMessage[256];
                snprintf(errorMessage, sizeof(errorMessage), "Failed to validate dependency '%s': %s", newDependency.c_str(), errorBuffer);
                // Log the error message...
            }
            curl_easy_cleanup(curl);
        } else {
            char errorMessage[64];
            snprintf(errorMessage, sizeof(errorMessage), "Failed to initialize cURL");
