```cpp
#include <fstream>
#include <sstream>

size_t loadResourceBundle(const std::string& filePath, std::vector<std::string>& bundle) {
    std::ifstream ifs(filePath);
    size_t count = 0;

    if (ifs.is_open()) {
        std::string line;
        while (getline(ifs, line)) {
            bundle.push_back(std::move(line));
            ++count;
        }
        ifs.close();
    }

    return count;
}
