from getpass import getpass

def replace_placeholders(configFilePath, placeholders):
    with open(configFilePath) as configFile:
        content = configFile.read()

    for placeholder in placeholders:
        content = content.replace(placeholder, getpass())

    outputFilePath = os.path.splitext(os.path.basename(configFilePath))[0] + '_modified.conf'
    subprocess.run(['sed', '-i', 's/OLD_PLACEHOLDER/' + placeholder + '/g', configFilePath], check=True)
    with open(outputFilePath, 'w') as outputFile:
        outputFile.write(content)

def addEncryptedPasswordLine(configFilePath):
    password = getpass()
    encrypted_password = encrypt_password(password)
    outputFilePath = os.path.splitext(os.path.basename(configFilePath))[0] + '_modified.conf'
    subprocess.run(['sed', '-i', '$aENCRYPTED_PLACEHOLDER=' + encrypted_password, configFilePath], check=True)
    with open(outputFilePath, 'w') as outputFile:
        # Add existing content and new line with the encrypted password
        with open(configFilePath) as inputFile:
            for line in inputFile.readlines():
                outputFile.write(line)
            outputFile.write('\nENCRYPTED_PLACEHOLDER=' + encrypted_password)
