Here is some boilerplate code for a simple log file processing module:

```cpp
#include <iostream>
#include <fstream>
#include <boost/property_tree/ptree.hpp>
#include <boost/filesystem.hpp>

namespace fs = boost::filesystem;
namespace pt = boost::property_tree;

void processLogFile(const std::string& filePath) {
    // Implement log parsing and metric calculation here.
}

int main() {
    std::string configFilePath = "config.yaml";
    fs::path configDir(".");
    fs::path configFile = configDir / configFilePath;

    if (!fs::exists(configFile)) {
        std::cerr << "Configuration file not found!" << std::endl;
        return 1;
    }

    pt::ptree tree;
    read_yaml(configFile, tree);

    // Read log directory from the configuration.
    auto logDirIt = tree.get<std::string>("log_directory");
    std::string logDirectory = *logDirIt;

    // Process all log files in the specified directory concurrently.
    boost::asio::io_context ioContext;
    int maxConcurrentTasks = tree.get<int>("max_concurrent_tasks");
    std::queue<std::string> taskQueue;

    for (const auto& entry : fs::directory_iterator(logDirectory)) {
        if (fs::is_regular_file(entry) && entry.path().extension() == ".log") {
            taskQueue.push(entry.path().string());
        }
    }

    std::vector<std::thread> workerThreads;
    for (int i = 0; i < maxConcurrentTasks; ++i) {
        workerThreads.emplace_back([&]() {
            while (!taskQueue.empty()) {
                auto task = taskQueue.front();
                taskQueue.pop();

                processLogFile(task);
            }
        });
    }

    // Start the ioContext and run all worker threads.
    ioContext.run();

    return 0;
}
```']

