typedef bgi::adjacency_list<bgi::vertex_property, bgi::edge_property, bgi::undirectedS> Graph;
typedef typename Graph::vertex_descriptor Vertex;
typedef typename Graph::edge_descriptor Edge;

void addVertexAndEdge(Graph& graph, const string& label, int property) {
    // Generate a new vertex and set properties...
    Vertex v = boost::add_vertex(graph);
    boost::set_property(v, label.c_str(), property);

    // Generate a new edge between the two vertices and set properties...
    Vertex w;
    if (graph.size() > 1) {
        w = *next(graph.begin());
    } else {
        w = boost::add_vertex(graph);
    }
    Edge e = boost::add_edge(v, w, graph).first;
    boost::set_property(e, label.c_str(), property);
}
```

