2. C# Function (AES-CBC Decryption):

```csharp
using System;
using System.Security.Cryptography;
using System.Text;

public byte[] DecryptAesCbc(byte[] ciphertext, byte[] key, byte[] iv) {
    using (Aes aes = Aes.Create()) {
        // Set encryption key and initialization vector
        aes.Key = key;
        aes.IV = iv;

        // Create decryptor to decrypt the encrypted data
        ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

        // Decrypt the ciphertext using CBC mode and PKCS7 padding scheme
        MemoryStream msDecrypt = new MemoryStream(ciphertext);
        CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
        byte[] buffer = new byte[msDecrypt.Size];
        int read;
        while ((read = csDecrypt.Read(buffer, 0, buffer.Length)) > 0) {
            msDecrypt.Read(buffer, read, buffer.Length - read);
        }
        return buffer;
    }
}
