fn compile_rs() -> (i32, u64) {
    let start = Instant::now();
    let mut rss = vec![0];
    if let Ok(mut file) = OpenOptions::new().read(true).open("/dev/shm/rustc.log") {
        fs::copy("/dev/null", &mut file)?;
    }
    let output = COMPILER.current_dir(env::current_dir().unwrap()).arg("--crate-name=test").output();
    if let Err(e) = output {
        eprintln!("Error during compilation: {}", e);
        return (1, 0);
    }
    if let Ok((status, stdout, stderr)) = output {
        rss[0] = get_resident_set_size()?;
        COMPILER.current_dir(env::current_dir().unwrap()).arg("--crate-name=test").args(&["run"]).output().and_then(|(_, _, e)| e.map(|e| (e.code().unwrap_or(1), 0)))?;
        let elapsed = start.elapsed().as_secs_f64();
        rss[0] = get_resident_set_size()? - rss[0];
    }
    (status.success(), rss[0])
}
