['```java
import org.joda.time.DateTime;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.Map;
import java.util.HashMap;

public class LogMessageFormatter {
    private static final ObjectMapper objectMapper = new ObjectMapper();

    private String logLevel;
    private DateTime timestamp;
    private Map<String, Object> messageContent;

    public LogMessageFormatter(String logLevel, Map<String, Object> messageContent) {
        this.logLevel = logLevel;
        this.messageContent = messageContent;
        this.timestamp = new DateTime();
    }

    public String formatAsJson() {
        Map<String, Object> jsonLogMessage = new HashMap<>();
        jsonLogMessage.put("level", this.logLevel);
        jsonLogMessage.put("time", this.timestamp.toString());
        jsonLogMessage.putAll(this.messageContent);
        return objectMapper.writeValueAsString(jsonLogMessage);
    }

    public String formatAsPlainText() {
        StringBuilder logMessage = new StringBuilder();
        logMessage.append("[");
        logMessage.append("level: ").append(this.logLevel);
        logMessage.append(", time: ").append(this.timestamp.toString());
        logMessage.append(", ");
        for (Map.Entry<String, Object> entry : this.messageContent.entrySet()) {
            if (entry.getKey() != null && !entry.getKey().isEmpty()) {
                logMessage.append(entry.getKey()).append(": ").append(entry.getValue());
                if (!entry.equals(this.messageContent.lastEntry())) {
                    logMessage.append(", ");
                }
            }
        }
        logMessage.append("]");
        return logMessage.toString();
    }
}
```

This `LogMessageFormatter` class supports customizable formatting of log messages, including log levels, timestamps, and message content. It provides options for encoding log messages into JSON or plain text. The class is extensible to accommodate future requirements such as new log levels or additional formatting options.']

