['1. C Function for Configuration File Loading:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>

typedef struct {
    char *key;
    char *value;
} ConfigPair;

int load_config(const char *filepath, ConfigPair **pairs, size_t *count) {
    struct stat st;
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) return 1;

    off_t filesize = stat(filepath, &st);
    if (filesize == -1) {
        close(fd);
        return 2;
    }

    char *mapped_memory = mmap(0, filesize + sizeof(size_t), PROT_READ, MAP_PRIVATE, fd, 0);
    if (mapped_memory == MAP_FAILED) {
        close(fd);
        return 3;
    }

    size_t current_position = 0;
    ConfigPair *pairs_buffer = malloc((filesize + sizeof(ConfigPair)) / sizeof(ConfigPair));
    if (!pairs_buffer) {
        munmap(mapped_memory, filesize + sizeof(size_t));
        close(fd);
        return 4;
    }

    char *line = mapped_memory;
    for (size_t i = 0; i < filesize / sizeof(ConfigPair); ++i) {
        size_t key_length = strcspn(line, "=");
        if (key_length == 0) break;

        ConfigPair *pair = &pairs_buffer[current_position++];
        pair->key = malloc(key_length + 1);
        memcpy(pair->key, line, key_length);
        pair->key[key_length] = '\0';

        size_t value_length = strlen(line + key_length + 1);
        pair->value = malloc(value_length + 1);
        memcpy(pair->value, line + key_length + 1, value_length);
        pair->value[value_length] = '\0';

        line += key_length + 1 + value_length + 1;
    }

    munmap(mapped_memory, filesize + sizeof(size_t));
    close(fd);

    *pairs = pairs_buffer;
    *count = current_position;

    return 0;
}
```

