["```sql
CREATE PROCEDURE GetProductDetailsExtended
    @SupplierID INT = NULL,
    @ProductTag VARCHAR(50) = NULL,
    @AdditionalAttributes NVARCHAR(MAX) = NULL,
    @UserDefinedColumn1 VARCHAR(50) = NULL,
    @UserDefinedColumn2 VARCHAR(50) = NULL,
    @UserDefinedColumn3 VARCHAR(50) = NULL,
    @ErrorLogID INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX);
    DECLARE @Params NVARCHAR(MAX);

    -- Set up SQL statement and parameters based on user input
    SET @SQL = 'SELECT P.*, C.CategoryName, S.SupplierName, S.ContactName';
    SET @SQL += (ISNULL(@AdditionalAttributes, '') + ',');
    SET @SQL += ' A.Attribute1, A.Attribute2, A.Attribute3';
    SET @Params = '@ProductID INT, @SupplierID INT, @ProductTag VARCHAR(50)';

    -- Add filtering conditions based on user input
    IF @SupplierID IS NOT NULL
        SET @SQL += ' FROM Products P';
    IF @SupplierID IS NOT NULL AND @ProductTag IS NOT NULL
        SET @SQL += ' INNER JOIN Suppliers S ON P.SupplierID = S.SupplierID';
    IF @ProductTag IS NOT NULL
        SET @SQL += ' INNER JOIN Categories C ON P.CategoryID = C.CategoryID';
    IF @AdditionalAttributes <> ''
        SET @SQL += ' INNER JOIN AdditionalAttributes A ON P.ProductID = A.ProductID';

    -- Add dynamic filtering based on user input
    IF @AdditionalAttributes IS NOT NULL AND (@UserDefinedColumn1 IS NOT NULL OR @UserDefinedColumn2 IS NOT NULL OR @UserDefinedColumn3 IS NOT NULL)
    BEGIN
        SET @SQL += ' WHERE';

        -- Add dynamic WHERE clause based on user input
        IF @UserDefinedColumn1 IS NOT NULL
            SET @SQL += ' P.' + @UserDefinedColumn1 + ' = @UserDefinedColumn1 AND';
        IF @UserDefinedColumn2 IS NOT NULL
            SET @SQL += ' P.' + @UserDefinedColumn2 + ' = @UserDefinedColumn2 AND';
        IF @UserDefinedColumn3 IS NOT NULL
            SET @SQL += ' P.' + @UserDefinedColumn3 + ' = @UserDefinedColumn3';

        -- Remove trailing AND
        SET @SQL = LEFT(@SQL, LEN(@SQL) - 5);
    END;

    -- Add support for additional filtering by product tag
    IF @ProductTag IS NOT NULL
        SET @SQL += ' AND P.ProductTag = @ProductTag';

    -- Add outer join for external APIs if required
    -- ...

    -- Log the SQL statement and parameters
    INSERT INTO ErrorLog (UserID, SQL, Parameters) VALUES (@UserID, @SQL + ';', @Params);

    -- Execute the query with the prepared statement
    EXEC sp_executesql @SQL, @Params, @ProductID = @ProductID, @SupplierID = @SupplierID, @ProductTag = @ProductTag, @UserDefinedColumn1 = @UserDefinedColumn1, @UserDefinedColumn2 = @UserDefinedColumn2, @UserDefinedColumn3 = @UserDefinedColumn3;

    -- Set output parameter for error handling
    SET @ErrorLogID = SCOPE_IDENTITY();
END;
```

