// Metadata validation and grouping function
void validate_and_group(std::vector<int>& numbers, const Comparator& comparator) {
    std::mutex mtx;
    std::vector<int> even_numbers;
    std::vector<int> odd_numbers;

    for (const auto& num : numbers) {
        std::lock_guard<std::mutex> lock(mtx);
        if (num % 2 == 0) {
            even_numbers.push_back(num);
        } else {
            odd_numbers.push_back(num);
        }
    }

    // Sort even and odd numbers separately and merge the results
    std::sort(even_numbers.begin(), even_numbers.end());
    std::sort(odd_numbers.begin(), odd_numbers.end());

    numbers.clear();
    numbers.insert(numbers.end(), even_numbers.cbegin(), even_numbers.cend());
    numbers.insert(numbers.end(), odd_numbers.cbegin(), odd_numbers.cend());
}

// External metadata validation class
