```javascript
function reduce(arr, initVal, callback) {
    return new Promise((resolve, reject) => {
        let accumulator = initVal;
        let i = 0;

        function reducer(accum, num) {
            if (i >= arr.length) {
                resolve(accum);
            } else {
                callback(accum, arr[i], (newAccum) => {
                    accumulator = newAccum;
                    i++;
                    reducer(accumulator, arr[i]);
                });
            }
        }

        reducer(accumulator, arr[0]);
    });
}
```

