};

class ThreadPool {
private:
    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex tasks_mutex_;
    std::condition_variable tasks_cv_;
    int min_workers_, max_workers_;

public:
    ThreadPool(int min_workers, int max_workers) : min_workers_(min_workers), max_workers_(max_workers) {}

    void enqueue(const std::function<void()>& task) {
        std::unique_lock<std::mutex> lock(tasks_mutex_);
        tasks_.push_back(task);
        tasks_cv_.notify_one();
    }

    void run() {
        for (int i = min_workers_; i <= max_workers_; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(tasks_mutex_);
                        tasks_cv_.wait(lock, [this] { return !tasks_.empty(); });
                        task = std::move(tasks_.front());
                        tasks_.pop_front();
                    }
                    task();
                }
            });
        }
    }
};

