void Microservice::sortData() {
    vector<pair<int, int>> sortedPairs;
    for (auto i : data) {
        if (i % 2 == 0)
            sortedPairs.push_back(make_pair(i, -1)); // mark even numbers for grouping
        else
            sortedPairs.push_back(make_pair(i, 1)); // odd numbers retain their relative order
    }

    sort(sortedPairs.begin(), sortedPairs.end());

    vector<int> result;
    for (auto pair : sortedPairs) {
        if (pair.second == -1) { // even numbers grouped together first
            while (!result.empty() && result.back() % 2 != 0)
                result.pop_back();
            result.push_back(pair.first);
        } else {
            result.push_back(pair.first);
        }
    }
    data = result;
}

