namespace EmployeeReportsService
{
    public class SupervisorReportService
    {
        private readonly string _connectionString;
        private readonly HttpClient _httpClient;

        public SupervisorReportService(string connectionString, HttpClient httpClient)
        {
            _connectionString = connectionString;
            _httpClient = httpClient;
        }

        public async Task<IDataReader> RetrieveSupervisorReportsAsync(int supervisorId)
        {
            try
            {
                // Verify supervisor ID with external identity service
                using (var request = new HttpRequestMessage())
                {
                    request.Method = HttpMethod.Get;
                    request.RequestUri = new Uri($"https://identity-service.com/verify?id={supervisorId}");
                    var response = await _httpClient.SendAsync(request);

                    if (!response.IsSuccessStatusCode)
                    {
                        throw new InvalidOperationException($"Failed to verify supervisor ID: {response.StatusCode}");
                    }
                }
            }
            catch (Exception ex)
            {
                throw new InvalidOperationException("Failed to verify supervisor ID", ex);
            }

            // Query the database for employee details if supervisor ID is verified
            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();

            using (var command = new SqlCommand($"SELECT EmployeeID, FirstName, LastName FROM Employees WHERE SupervisorID = {supervisorId}", connection))
            {
                return await command.ExecuteReaderAsync();
            }
        }
    }
}
```

