import com.zaxxer.hikari.HikariDataSource;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class ConfigManager {
    private final HikariDataSource dataSource;

    public ConfigManager(String jdbcUrl, String username, String password) {
        dataSource = new HikariDataSource();
        dataSource.setJdbcUrl(jdbcUrl);
        dataSource.setUsername(username);
        dataSource.setPassword(password);
    }

    public SensorThreshold getThreshold(int tenantId) throws SQLException {
        try (Connection connection = dataSource.getConnection()) {
            PreparedStatement statement = connection.prepareStatement("SELECT threshold FROM tenants WHERE id = ?");
            statement.setInt(1, tenantId);
            ResultSet resultSet = statement.executeQuery();
            if (resultSet.next()) {
                double threshold = resultSet.getDouble("threshold");
                return new SensorThreshold(tenantId, threshold);
            }
        }
        // Return a default threshold or handle the case of an empty configuration
    }

    public void updateThreshold(int tenantId, double threshold) throws SQLException {
        try (Connection connection = dataSource.getConnection()) {
            PreparedStatement statement = connection.prepareStatement("UPDATE tenants SET threshold = ? WHERE id = ?");
            statement.setDouble(1, threshold);
            statement.setInt(2, tenantId);
            statement.executeUpdate();
        }
    }
}
