2. JavaScript Function:
```javascript
function refreshDialogFields(fieldNames, callback) {
  const messages = fieldNames.map(name => ({ name, data: null }));
  window.postMessage({ type: 'REFRESH_FIELDS', payload: messages }, '*');

  const handler = e => {
    if (e.data && e.data.type === 'REFRESH_FIELD') {
      for (const message of messages) {
        if (message.name === e.data.payload.name) {
          message.data = e.data.payload.data;
          break;
        }
      }
      if (messages.every(msg => msg.data)) {
        callback();
        window.removeEventListener('message', handler);
      }
    }
  };
  window.addEventListener('message', handler);
}
```"]

