vector<int> PokemonService::sortAndGroupEvenNumbers(const vector<int>& numbers, const std::function<bool(int, int)>& comparator) {
    vector<int> evenNumbers;
    vector<int> oddNumbers;
    for (auto num : numbers) {
        if (num % 2 == 0) {
            evenNumbers.push_back(num);
        } else {
            oddNumbers.push_back(num);
        }
    }
    sort(evenNumbers.begin(), evenNumbers.end(), comparator);
