    let redis_client = Client::open(config.redis_url).unwrap();
    let session_manager = SessionManager::new_redis(redis_client, RedisSessionKey::default());

    let service_clones: Vec<Arc<dyn Fn() -> Box<dyn RequestHandler>>> = config
        .service_list
        .iter()
        .map(|name| {
            Arc::new(move || Box::new(load_service(name).unwrap()))
        })
        .collect();

