```

4. Implement concurrent-safe dynamic array module:

```c
#define DYNAMIC_ARRAY_GROWTH 1024 // or any other suitable growth factor

struct dynamic_array {
    struct LTE_PHY_RX_TARGETED_INFO* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    sem_t semaphore;
};

void init_dynamic_array(struct dynamic_array *array, size_t initial_size) {
    array->capacity = initial_size;
    array->count = 0;
    array->data = custom_malloc(initial_size * sizeof(struct LTE_PHY_RX_TARGETED_INFO));
    pthread_mutex_init(&array->lock, NULL);
    sem_init(&array->semaphore, 0, initial_size);
}

void resize_dynamic_array(struct dynamic_array *array) {
    array->capacity *= DYNAMIC_ARRAY_GROWTH;
    array->data = realloc(array->data, array->capacity * sizeof(struct LTE_PHY_RX_TARGETED_INFO));
}

void push_back(struct dynamic_array *array, const struct LTE_PHY_RX_TARGETED_INFO item) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        resize_dynamic_array(array);
    }
    array->data[array->count] = item;
    array->count++;

    sem_post(&array->semaphore);
    pthread_mutex_unlock(&array->lock);
}
```

