#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>
#include <pthread.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct api_response {
    const char* response_data;
    size_t response_size;
} API_RESPONSE_T;

API_RESPONSE_T fetch_ue_info(const char* api_url);
bool compute_checksum(const void* data, size_t length, uint8_t* checksum);
void md5_hash(const void* data, size_t length, uint8_t digest[MD5_DIGEST_LENGTH]);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* generate_ue_info(int n) {
    NFAPI_CRC_INDICATION_PDU_T* ue_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ue_list) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_t threads[n];
    API_RESPONSE_T response;

    for (int i = 0; i < n; ++i) {
        response = fetch_ue_info(/* your external API URL */);
        if (!response.response_data || !response.response_size) {
            perror("Failed to fetch UE info");
            continue;
        }

        pthread_create(&threads[i], NULL, process_ue_info, &response);
    }

    for (int i = 0; i < n; ++i) {
        pthread_join(threads[i], NULL);
    }

    return ue_list;
}

void* process_ue_info(void* arg) {
    API_RESPONSE_T* response = (API_RESPONSE_T*)arg;

    NFAPI_CRC_INDICATION_PDU_T* ue_info = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ue_info) {
        perror("Memory allocation failed");
        goto cleanup;
    }

    pthread_mutex_lock(&lock);
    memcpy(ue_info, parse_response(*response), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&lock);

    uint8_t checksum;
    if (!compute_checksum(ue_info, sizeof(NFAPI_CRC_INDICATION_PDU_T), &checksum)) {
        perror("Failed to compute checksum");
        goto cleanup;
    }

    ue_info->CRCFLAG = checksum == 0;

    md5_hash(ue_info, sizeof(NFAPI_CRC_INDICATION_PDU_T), ue_info->MD5);

cleanup:
    free(ue_info);
    return NULL;
}
```

