void *populateNfarxIndications(void *args) {
    NFAPI_CRC_INDICATION_PDU_T **list_ptr = args;
    size_t num_items = *((size_t*)args + 1);
    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    bool is_caching_enabled = (cache != NULL);

    if (num_items > max_concurrency) {
        num_items = max_concurrency;
    }

    for (size_t i = 0; i < num_items; ++i) {
        if (is_caching_enabled && cache != NULL) {
            // Check cache before retrieving from external data source.
            if (cache->rxi_ue_information_tag != 0) {
                current = cache;
                cache_hit_count++;
            } else {
                cache_miss_count++;
                NFAPI_CRC_INDICATION_PDU_T *cached_items = populate_cache();
                if (current == NULL) {
                    current = cached_items;
                    cache = cached_items;
                } else {
                    while (current->next != NULL) {
                        current = current->next;
                    }
                    current->next = cached_items;
                    cache = NULL;
                }
            }
        } else {
            // Retrieve data directly from external data source.
            NFAPI_CRC_INDICATION_PDU_T *cached_items = populate_cache();
            if (current == NULL) {
