                    current = current->next;
                }
                current->next = cached_items;
            }
        }

        // Populate the structure and advance to the next item.
        current->rxi_ue_information_tag = i + 1;
        current->rnti = i;
        current->crc_indication_rel8_tag = rand() % 256;
        current->crcflag = rand() % 2 == 0;

        if (current->next == NULL) {
            current->next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else {
            current = current->next;
        }
    }

    pthread_mutex_lock(&performance_lock);
    total_items += num_items;
    pthread_mutex_unlock(&performance_lock);

    return head;
