typedef struct {
    double min;
    double max;
    double seed;
    pthread_mutex_t lock;
} RVGConfig;

RVGConfig rvg_config;

void set_rvg_config(double min, double max, double seed) {
    // validation checks and error handling
    rvg_config.min = min;
    rvg_config.max = max;
    rvg_config.seed = seed;
}

double random_value() {
    pthread_mutex_lock(&rvg_config.lock);
    double rand = (rand() * (1.0 / RAND_MAX)) * (rvg_config.max - rvg_config.min) + rvg_config.min;
    // handle out-of-range cases
    if (rand < rvg_config.min || rand > rvg_config.max) {
        rand = rvg_config.min + (rvg_config.max - rvg_config.min) * 0.5;
    }
    pthread_mutex_unlock(&rvg_config.lock);
    return rand;
}
