[' Here is a simplified version of the SecureHashUtil class in Java, using Apache Commons Lang for hashing and Ehcache for caching. This implementation does not include all the features you requested but provides a foundation for further development.

```java
import org.apache.commons.codec.digest.DigestUtils;
import net.sf.ehcache.Cache;
import net.sf.ehcache.Element;

import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.*;

public class SecureHashUtil {
    private static final int MAX_THREADS = 10;
    private static final Cache<String, String> cache = EhcacheFactory.createCache("SecureHashes", 1000, true, false);
    private static final List<Algorithm> SUPPORTED_ALGORITHMS = Collections.unmodifiableList(Arrays.asList(Algorithm.MD5, Algorithm.SHA256, Algorithm.SHA384));

    public static class Algorithm {
        public final String name;
        public Algorithm(String name) {
            this.name = name;
        }
    }

    private ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

    public String generateHash(String input, String algorithmName) throws InvalidAlgorithmException {
        Algorithm algorithm = findSupportedAlgorithmByName(algorithmName);
        return cache.getOrCreateElement(input + "_" + algorithm.name, () -> computeHash(input, algorithm)).getObjectValue();
    }

    private Algorithm findSupportedAlgorithmByName(String algorithmName) throws InvalidAlgorithmException {
        for (Algorithm algorithm : SUPPORTED_ALGORITHMS) {
            if (algorithm.name.equalsIgnoreCase(algorithmName)) {
                return algorithm;
            }
        }
        throw new InvalidAlgorithmException("Unsupported algorithm: " + algorithmName);
    }

    private String computeHash(String input, Algorithm algorithm) {
        try {
            switch (algorithm) {
                case MD5:
                    return DigestUtils.md5Hex(input);
                case SHA256:
                    return DigestUtils.sha256Hex(input);
                case SHA384:
                    return DigestUtils.sha384Hex(input);
                default:
                    throw new RuntimeException("Unexpected algorithm: " + algorithm);
            }
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public List<String> bulkHash(List<String> inputs) {
        CompletionService<Future<String>> completionService = new ExecutorCompletionService<>(executor);
        for (String input : inputs) {
            Future<String> futureResult = completionService.submit(() -> generateHash(input, Algorithm.SHA256.name));
            completionService.submit(futureResult::get);
        }
        List<Future<String>> futures = completionService.takeAll().values();
        return futures.stream().map(f -> {
            try {
                return f.get();
            } catch (ExecutionException | InterruptedException e) {
                throw new RuntimeException(e);
            }
        }).collect(Collectors.toList());
    }
}
```

This class includes support for three hash algorithms, MD5, SHA-256, and SHA-384. It utilizes a thread pool to process inputs concurrently and an Ehcache instance as a simple caching mechanism. The `generateHash()` method returns precomputed hashes from the cache when possible, while computing new hashes using the Apache Commons Lang library for hashing.

The `bulkHash()` method leverages a CompletionService to process a list of inputs concurrently and efficiently.']

