def modify_kickstart_config(params: Dict[str, str]):
    config_file = "path/to/kickstart.cfg"
    for key, value in params.items():
        command = f"sed -i 's|{key}|{value}|g' {config_file}"
        try:
            subprocess.check_call(command, shell=True)
        except subprocess.CalledProcessError as e:
            raise Exception(f"Failed to replace '{key}' in configuration file")
    password = hashlib.sha256(os.urandom(16)).hexdigest()
    command = f"echo 'password={password}' >> {config_file}"
    subprocess.check_call(command, shell=True)
