public class ExternalApiClient {
    private RetryPolicy retryPolicy;

    public ExternalApiClient(RetryPolicy retryPolicy) {
        this.retryPolicy = retryPolicy;
    }

    public void callExternalAPI(Callable<Response> callable) throws ExecutionException, InterruptedException {
        Response response = null;
        while (true) {
            try {
                response = callable.call();
                break;
            } catch (Exception e) {
                if (!retryPolicy.shouldRetry(e)) {
                    throw e;
                }
            }
        }
    }
}
