```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Data.Common;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using StackExchange.Redis;

public class DbService
{
    private readonly ILogger _logger;
    private readonly IDatabase _db;
    private readonly ConnectionMultiplexer _redis;
    private readonly List<string> _connectionStrings;

    public DbService(ILoggerFactory loggerFactory, IConfiguration configuration)
    {
        _logger = loggerFactory.CreateLogger<DbService>();
        _redis = ConnectionMultiplexer.Connect(_ => configuration.GetConnectionString("Redis"));
        _db = _redis.GetDatabase();
        _connectionStrings = configuration.GetSection("Database").GetChildren().Select(x => x.Value).ToList();
    }

    public async Task ProcessAsync(byte[] data)
    {
        var db = GetConnectedDb();
        await db.ExecuteNonQueryAsync("INSERT INTO Data (Data) VALUES (@data)", new DbParameter("@data", data));
    }

    private IDatabase GetConnectedDb()
    {
        if (_db.Connection.IsOpen) return _db;

        var dbIndex = (_db.Connection.Information.DatabaseId % _connectionStrings.Count);
        var connectionString = _connectionStrings[dbIndex];
        _db.Connect(connectionString, CommandFlags.None);
        return _db;
    }
}
```

