import hashlib
import os
import time
import concurrent.futures
from google.oauth2 import service_account
from googleapiclient.discovery import build
from googleapiclient.errors import HttpError

def get_hash(file_path, hash_type='md5'):
    with open(file_path, 'rb') as f:
        hasher = hashlib.new(hash_type)
        while True:
            data = f.read(65536)
            if not data:
                break
            hasher.update(data)
        return hasher.hexdigest()

def upload_to_storage(file, storage_client):
    bucket_name = 'my-bucket'
    blob_name = os.path.basename(file)
    storage_client.create_blob(bucket_name, blob_name, file)

def log_hash(hash, hash_type='md5'):
    scopes = ['https://www.googleapis.com/auth/cloud-platform']
    service_account_file = 'path/to/service_account.json'
    credentials = service_account.Credentials.from_service_account_file(service_account_file, scopes)

    youtube_api_service = build('logging', 'v3', credentials=credentials)
    log_name = f"hash_{hash_type}"
    resource = youtube_api_service.projects().logs().write(logName='projects/*/logs/{log_name}', body={'resource': {'data': [{'insertId': hash}]}})
    try:
        resource.execute()
    except HttpError as error:
        print(f'An error occurred: {error}')

def process_file(file, storage_client):
    hash = get_hash(file)
    log_hash(hash)

def main():
    storage_client = build('storage', 'v1', )  # Initialize your Google Cloud Storage client here
    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = {executor.submit(process_file, file, storage_client): file for file in os.listdir('/path/to/files')}
        for future in concurrent.futures.as_completed(futures):
            try:
                _ = future.result()
            except Exception as e:
                print(f'An error occurred while processing {future.argument}: {e}')
                log_error(e)
