```cpp
#include <cstdint>
#include <deque>
#include <random>
#include <memory>
#include <mutex>
#include <condition_variable>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
};

class PDULinkedList {
public:
    void push_back(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::unique_lock<std::mutex> lock(mtx);
        pdus.push_back(pdu);
        cv.notify_one();
    }

    void merge() {
        std::unique_lock<std::mutex> lock(mtx);
        while (!pdus.empty()) {
            auto it = pdus.begin();
            pdus.erase(it);
            mergedPDUs.push_back(*it);
        }
    }

private:
    std::deque<NFAPI_CRC_INDICATION_PDU_T> pdus;
    std::deque<NFAPI_CRC_INDICATION_PDU_T> mergedPDUs;
    std::mutex mtx;
    std::condition_variable cv;
};

void generateAndMergeNfarxPdus(PDULinkedList& list) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, UINT32_MAX);

    for (size_t i = 0; i < NUM_PDUS; ++i) {
        auto pdu = NFAPI_CRC_INDICATION_PDU_T{dis(gen), static_cast<uint64_t>(dis(gen)), CRC_INDICATION_REL8_TAG()};
        list.push_back(pdu);
    }

    while (true) {
        std::unique_lock<std::mutex> lock(list.mtx);
        list.cv.wait(lock, [&](){ return !list.pdus.empty(); });
        list.merge();
    }
}
```

