    std::forward_list<std::unique_ptr<ValidationService>> services_;
    std::map<std::string, std::unique_ptr<ValidationService>> serviceRegistry_;
    std::priority_queue<std::function<void()>, std::vector<std::function<void()>>> tasks_;
    std::atomic<bool> running_{true};
    std::condition_variable cv_;

public:
    void addService(const std::string& name, std::unique_ptr<ValidationService> service) {
        std::lock_guard<std::mutex> lock(mtx_);
        services_.push_back(std::move(service));
        serviceRegistry_[name] = std::move(service);
    }

    void removeService(const std::string& name) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = serviceRegistry_.find(name);
        if (it != serviceRegistry_.end()) {
            services_.remove_if([it](auto& s) { return &*s->get() == it->second.get(); });
            serviceRegistry_.erase(it);
        }
    }

