**Java SecureHashUtil:**

```java
import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.Arrays;

public final class SecureHashUtil {
    private static final String[] ALGORITHMS = {"MD5", "SHA-256", "SHA-384"};

    public static byte[] hash(String algorithm, byte[] input) throws Exception {
        MessageDigest messageDigest = MessageDigest.getInstance(algorithm);
        messageDigest.update(input);
        return messageDigest.digest();
    }

    public static String getHashAsHex(byte[] hash) {
        BigInteger bi = new BigInteger(1, hash);
        String hex = bi.toString(16);
        while (hex.length() < 64) {
            hex = "0" + hex;
        }
        return hex;
    }

    public static void main(String[] args) throws Exception {
        for (String algorithm : ALGORITHMS) {
            String input = "Hello, World!";
            byte[] inputBytes = input.getBytes("UTF-8");
            System.out.printf("%s: %s\n", algorithm, getHashAsHex(hash(algorithm, inputBytes)));
        }
    }
}
```

