class LogAggregator {
public:
    struct Config {
        std::string cloud_service;
        int buffering_window;
        // Additional configuration options...
    };

    virtual ~LogAggregator() {}

    static LogAggregator& getInstance(const Config& config) {
        static LogAggregator instance(config);
        return instance;
    }

    void addDeviceData(const std::vector<float>& data);
    void process();
    const std::map<int, std::vector<float>>& getHistoricalSummaries() const { return historical_summaries_; }

private:
    LogAggregator(const Config& config) : bufferingQueue_(config.buffering_window), config_(config) {}

    void processDeviceData();
    void processBuffer();
    void syncWithCloud();

    std::map<int, std::vector<float>> historical_summaries_;
    std::queue<std::vector<float>> bufferingQueue_;
    Config config_;
};

void LogAggregator::addDeviceData(const std::vector<float>& data) {
    for (const auto& value : data) {
        historical_summaries_[value.first].push_back(value.second);
    }
}

void LogAggregator::process() {
    boost::thread_group threads;
    for (size_t i = 0; i < numThreads_; ++i) {
        threads.create_thread(&LogAggregator::processDeviceData, this);
    }
    threads.join_all();
}

void LogAggregator::processDeviceData() {
    while (true) {
        if (!bufferingQueue_.empty()) {
            processBuffer();
        }
        boost::this_thread::sleep(boost::posix_time::milliseconds(10));
    }
}

void LogAggregator::processBuffer() {
