3. **DependencyManager (C++)**
   ```cpp
   #include <list>
   #include <iterator>

   class DependencyManager {
       std::forward_list<std::string> dependencies;

       void insertAfter(const std::string& dependency, const std::string& newDependency) {
           auto it = dependencies.begin();
           for (; it != dependencies.end() && it->compare(dependency) < 0; ++it);
           if (it != dependencies.end()) {
               it = dependencies.insertAfter(it, newDependency);
           } else {
               dependencies.push_back(newDependency);
           }
       }

   public:
       void addDependency(const std::string& dependency) {
           insertAfter(dependency, dependency);
       }

       void addDependencyAfter(const std::string& mainDependency, const std::string& newDependency) {
           insertAfter(mainDependency, newDependency);
       }
   };
   ```"]

