  const criteria = await fetchCriteria();

  // Prepare a list of promises representing each API call
  const apiPromises = criteria.apis.map((api) => fetchData(api.url, qs.parse(api.params)));

  // Use Promise.all with a concurrency limit to distribute tasks across workers
  const dataResults = await Promise.all(apiPromises.slice(0, workerPool.concurrencyLimit)).then(() =>
    apiPromises.slice(workerPool.concurrencyLimit)
