                    .retryWhen(errors -> errors.flatMap(e -> Mono.delay(Duration.ofSeconds(5)).thenReturn(Mono.empty())))
                    .doOnError(ex -> LOGGER.error("Error saving to database: {}", ex.getMessage()));

            Sink<Void> esSink = Mono.fromCallable(() -> saveToElasticSearch(feedback))
                    .retryWhen(errors -> errors.flatMap(e -> Mono.delay(Duration.ofSeconds(5)).thenReturn(Mono.empty())))
