**Code Snippets:**

1. Function to fetch the PEM certificate from a specified location:

```c
#include <openssl/pem.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *get_certificate(const char *oauth_request) {
    const char *private_key_path = oauth_request + ...; // Extract private key path from request
    const char *certificate_path = oauth_request + ...; // Extract certificate path from request

    EVP_PKEY *priv_key;
    STACK_OF(X509) *cert_stack;
    BIO *mem_bio = NULL, *priv_bio = NULL, *cert_bio = NULL;
    X509 *x509;

    // Initialize BIO structures
    mem_bio = BIO_new(BIO_s_mem());
    priv_bio = BIO_new_file(private_key_path, "r");
    cert_bio = BIO_new_file(certificate_path, "r");

    // Load private key and certificate from files
    PEM_read_PrivateKey(priv_bio, NULL, NULL, NULL);
    cert_stack = PEM_X509_readef(cert_bio, NULL, 0, NULL);

    // Combine private key and certificate into a single PEM file
    x509 = X509_new();
    X509_set_cert_chain(x509, cert_stack);
    i2d_X509(x509, NULL);
    unsigned long len = X509_get_der(x509);
    void *buf = OPENSSL_malloc(len);
    i2d_X509(x509, &buf);
    BIO_puts(mem_bio, buf);
    EVP_encode_private_key(EVP_pkey_get1_RSA(priv_key), buf, NULL);
    BIO_puts(mem_bio, (char *)EVP_CIPHER_get_name(priv_key->type));
    BIO_flush(mem_bio);

    // Clean up and return the PEM-encoded certificate
    X509_free(x509);
    EVP_PKEY_free(priv_key);
    PEM_write_bio_PrivateKey(mem_bio, priv_key, NULL, NULL, 0, NULL, NULL);
    BIO_get_mem_ptr(mem_bio);

    // Clean up BIO structures
    BIO_free(mem_bio);
    BIO_free(priv_bio);
    BIO_free(cert_bio);
}
```

