void read_and_transform(const char* input_file, const char* output_file, char** transformation_rules) {
    FILE *in_fp = fopen(input_file, "rb");
    if (!in_fp) {
        perror("Error opening input file");
        return;
    }

    FILE *out_fp = fopen(output_file, "wb");
    if (!out_fp) {
        perror("Error opening output file");
        fclose(in_fp);
        return;
    }

    size_t in_len = 0;
    char *input_buffer = NULL;
    size_t out_len = 0;
    char *output_buffer = NULL;

    while ((in_len = fread(input_buffer, 1, sizeof(input_buffer), in_fp)) > 0) {
        output_buffer = realloc(output_buffer, out_len + in_len);
        memcpy(&output_buffer[out_len], input_buffer, in_len);
        out_len += in_len;

