class ResourceManager {
public:
    // Function for adding a new configuration bundle from a given file source
    void addBundle(const std::string& filename);

    // Function for removing an existing configuration bundle by its filename
    void removeBundle(const std::string& filename);

    // Function for retrieving the value of a specific key across all bundles
    const Config* getConfig(const std::string& key);

private:
    std::vector<YAML::Node> bundles;  // Stores YAML nodes for each configuration bundle
    std::mutex dataMutex;           // Protects the internal data structure from concurrent access
    std::map<std::string, int> filenames;   // Maps filenames to indices in the bundles vector for fast lookups
};

void ResourceManager::addBundle(const std::string& filename) {
    // Read the YAML file and parse it into a YAML::Node
    // Add the node to the bundles vector and update the filenames map
}

void ResourceManager::removeBundle(const std::string& filename) {
    auto it = filenames.find(filename);
    if (it != filenames.end()) {
        int index = it->second;
        bundles.erase(index);
        filenames.erase(it);
    }
}

const Config* ResourceManager::getConfig(const std::string& key) {
    std::lock_guard<std::mutex> lock(dataMutex);

    for (const auto& bundle : bundles) {
        if (auto it = bundle.FindValue(key)) {
            return new Config{ key, it->as<std::string>() };
        }
    }

    return nullptr;
}
```

