// Octree node structure
struct Node {
    int id;
    std::vector<Node*> children;
    std::string content;
    size_t featureSize;
    bool leaf;
};

class Octree {
public:
    Octree(size_t leafNodes) : root(0), leafNodes_(leafNodes) {}

    void addContent(const std::string& html, int sectionId, int elementId);
    void refresh(); // Refresh the octree with new data from a backend service

private:
    Node* findNodeById(Node* node, int id);
    void createNode(Node* parent, const std::string& content, size_t featureSize, bool leaf);
    void updateNodeContent(Node* node, const std::string& content);

    Node* root;
    size_t leafNodes_;
    boost::mutex mutex_;
};

void Octree::addContent(const std::string& html, int sectionId, int elementId) {
    // Parse HTML and find the desired section and element IDs
    lxml::html::document doc;
    lxml::html::element rootElement = doc.parse_string(html);

    // Your parsing logic here to find the correct section and element IDs

    if (sectionId != -1 && elementId != -1) {
        Node* node = findNodeById(root, sectionId);
        if (node) {
            std::string content = extractContentFromElement(rootElement, elementId);
            createOrUpdateNode(node, content);
        }
    }
}

void Octree::refresh() {
    // Your logic here to fetch additional metadata from a backend service
}

Node* Octree::findNodeById(Node* node, int id) {
    if (!node) return nullptr;

    if (node->id == id && node->leaf) return node;

    for (auto& child : node->children) {
        Node* found = findNodeById(child, id);
        if (found) return found;
    }

    return nullptr;
}

void Octree::createOrUpdateNode(Node* parent, const std::string& content) {
    Node* node = findNodeById(parent, content.hash<std::string>().key);

    if (!node) {
        createNode(parent, content, parent->featureSize, false);
    } else if (!node->leaf && node->content != content) {
        updateNodeContent(node, content);
    }
}

void Octree::createNode(Node* parent, const std::string& content, size_t featureSize, bool leaf) {
    Node* newNode = new Node();
    newNode->id = content.hash<std::string>().key;
    newNode->content = content;
    newNode->featureSize = featureSize;
    newNode->leaf = leaf;

    if (!parent->leaf) {
        // Ensure parent node has enough children to accommodate the new node
        if (parent->children.size() == parent->leafNodes_) {
            createOrUpdateNode(parent, content);
        } else {
            parent->children.push_back(newNode);
        }
    } else {
        // Create a new leaf node
        parent->children.clear();
        parent->children.push_back(newNode);
    }
}

void Octree::updateNodeContent(Node* node, const std::string& content) {
    node->content = content;

    if (node->leaf && node->featureSize < parent_->featureSize) {
        // Create new child nodes to split the node when it becomes too large
        size_t index = static_cast<size_t>(rand() % node->children.size());
        Node* childToSplit = node->children[index];

        if (childToSplit->leaf) {
            createOrUpdateNode(node, content);
        } else {
            // Continue splitting the tree recursively until reaching a leaf node or exceeding the maximum depth
            updateNodeContent(childToSplit, content);
        }
    }
}

