class DistributedLock {
    private $client; // Redis client or another distributed lock provider

    public function __construct($lockKey) {
        $this->client = new \Predis\Client();
    }

    public function acquireLock() {
        return $this->client->set($lockKey, 'locked', array('ex' => 30));
    }

    public function releaseLock() {
        return $this->client->delete($lockKey);
    }
}
